class Solution {
    public int getMaxLen(int[] nums) {
        int n = nums.length;
        int maxLen = 0;
        int i = 0;
        while (i < n) {
            // skip zeros, start a new segment
            while (i < n && nums[i] == 0) {
                ++i;
            }
            if (i == n) {
                break;
            }
            int segStart = i;
            int negCnt = 0;
            int firstNeg = -1;
            int lastNeg = -1;
            // process current zero‑free segment
            while (i < n && nums[i] != 0) {
                if (nums[i] < 0) {
                    ++negCnt;
                    if (firstNeg == -1) {
                        firstNeg = i;
                    }
                    lastNeg = i;
                }
                ++i;
            }
            int segLen = i - segStart;
            if (negCnt % 2 == 0) {
                if (segLen > maxLen) {
                    maxLen = segLen;
                }
            } else {
                // drop prefix up to first negative or suffix after last negative
                int dropPrefix = firstNeg - segStart + 1;
                int dropSuffix = i - lastNeg;
                int candidate = Math.max(segLen - dropPrefix, segLen - dropSuffix);
                if (candidate > maxLen) {
                    maxLen = candidate;
                }
            }
        }
        return maxLen;
    }
}

