var getMaxLen = function(nums) {
    const n = nums.length;
    let maxLen = 0;
    let i = 0;
    while (i < n) {
        // skip zeros, start a new segment
        while (i < n && nums[i] === 0) ++i;
        if (i === n) break;
        const segStart = i;
        let negCnt = 0;
        let firstNeg = -1, lastNeg = -1;
        // process current zero‑free segment
        while (i < n && nums[i] !== 0) {
            if (nums[i] < 0) {
                ++negCnt;
                if (firstNeg === -1) firstNeg = i;
                lastNeg = i;
            }
            ++i;
        }
        const segLen = i - segStart;
        if (negCnt % 2 === 0) {
            maxLen = Math.max(maxLen, segLen);
        } else {
            // drop prefix up to first negative or suffix after last negative
            const dropPrefix = firstNeg - segStart + 1;
            const dropSuffix = i - lastNeg;
            const candidate = Math.max(segLen - dropPrefix, segLen - dropSuffix);
            maxLen = Math.max(maxLen, candidate);
        }
    }
    return maxLen;
};
